<?php
$picked=array_map('strval',$pickerSelected);$available=[];$byId=[];
foreach($pickerRows as $row){$row['title']=$row['title']??$row['name']??'';$byId[(string)$row['id']]=$row;}
$chosen=[];foreach($picked as $id)$chosen[]=$byId[$id]??['id'=>$id,'title'=>'Yayında olmayan / bulunamayan kayıt #'.$id,'unavailable'=>true];
foreach($byId as $id=>$row)if(!in_array((string)$id,$picked,true))$available[]=$row;
$renderChoice=static function($row,$checked)use($pickerField):void{
    $id='pick-'.substr(hash('sha256',$pickerField.':'.$row['id']),0,14);
    ?><div class="region-picker-item" data-picker-item data-unavailable="<?= !empty($row['unavailable'])?'1':'0' ?>" data-search="<?= e(mb_strtolower($row['title'].' '.($row['category']??''),'UTF-8')) ?>"><label for="<?= $id ?>"><input id="<?= $id ?>" type="checkbox" name="<?= e($pickerField) ?>[]" value="<?= e((string)$row['id']) ?>" <?= $checked?'checked':'' ?>><span><strong><?= e($row['title']) ?></strong><small><?= !empty($row['unavailable'])?'Sitede gösterilmez. Kaldırabilir veya yayına aldığınızda yeniden kullanabilirsiniz.':e($row['category']??($row['slug']??'Aktif içerik')) ?></small></span></label><div class="region-picker-actions"><button type="button" data-picker-move="up" aria-label="<?= e($row['title']) ?> kaydını yukarı taşı">↑</button><button type="button" data-picker-move="down" aria-label="<?= e($row['title']) ?> kaydını aşağı taşı">↓</button><button type="button" data-picker-remove aria-label="<?= e($row['title']) ?> seçimini kaldır">×</button></div></div><?php
};
?>
<div class="region-picker" data-content-picker="<?= e($pickerType) ?>"><div class="region-picker-heading"><h3>Sayfaya eklenenler <span data-picker-count><?= count($chosen) ?></span></h3><small>En fazla <?= $pickerType==='services'?24:120 ?> kayıt</small></div><div class="region-picker-selected" data-picker-selected><?php foreach($chosen as $row)$renderChoice($row,true); ?></div><p class="region-picker-empty" data-picker-empty <?= $chosen?'hidden':'' ?>>Henüz seçim yapılmadı. Aşağıdaki listeden ekleyin.</p>
<div class="region-picker-library"><div><h3>İçerik kütüphanesi</h3><label for="picker-search-<?= e($pickerType) ?>">İsim veya kategori ara</label><input id="picker-search-<?= e($pickerType) ?>" class="form-control" type="search" placeholder="Bu içerik türünde ara..." data-picker-search></div><div class="region-picker-available" data-picker-available><?php foreach($available as $row)$renderChoice($row,false); ?></div><p class="region-picker-empty" data-picker-no-results hidden>Aramanıza uygun içerik yok.</p></div><p class="region-picker-status" data-picker-status role="status" aria-live="polite"></p></div>
